package com.anaiv.fluxogestao.porto;
import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.Collection; import java.util.List; import java.util.Optional;
public interface OrdemPagamentoPortoRepository extends JpaRepository<OrdemPagamentoPorto,Long>{Optional<OrdemPagamentoPorto> findByNumero(String numero);List<OrdemPagamentoPorto> findByNumeroIn(Collection<String> numeros);@Query("select distinct op from OrdemPagamentoPorto op left join fetch op.calendarioPagamento left join fetch op.importacao")List<OrdemPagamentoPorto> findAllParaListagem();@Query("select op.numero from OrdemPagamentoPorto op where op.numero in :numeros")List<String> numerosExistentes(@Param("numeros") Collection<String> numeros);}
